<?php
declare(strict_types=1); require_once __DIR__.'/bootstrap.php'; admin_require_login();
$action=(string)($_GET['action']??''); $id=(int)($_GET['id']??0); $errors=[];
$categories=$pdo->query('SELECT id,name,parent_id FROM categories ORDER BY name')->fetchAll(); $parentProducts=$pdo->query('SELECT id,name FROM products ORDER BY name')->fetchAll(); $brands=$pdo->query('SELECT id,name FROM brands ORDER BY name')->fetchAll(); $mediaFiles=[]; foreach(glob(__DIR__.'/../uploads/products/*.{jpg,jpeg,png,webp,gif}',GLOB_BRACE)?:[] as $mf){$mediaFiles[]='uploads/products/'.basename($mf);}
$product=['category_id'=>'','parent_product_id'=>'','brand_id'=>'','name'=>'','slug'=>'','sku'=>'','short_description'=>'','description'=>'','specifications'=>'','price'=>'','compare_at_price'=>'','cost_price'=>'','stock_quantity'=>'0','low_stock_threshold'=>'5','image_path'=>'','is_featured'=>0,'is_active'=>1];
if ($action==='edit' && $id>0) { $s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([$id]);$found=$s->fetch();if(!$found){http_response_code(404);exit('Product not found.');}$product=$found; if(!empty($product['specifications'])){ $decoded=json_decode((string)$product['specifications'],true); if(is_array($decoded)){ $lines=[]; foreach($decoded as $k=>$v)$lines[]=is_int($k)?(string)$v:($k.': '.$v); $product['specifications']=implode("\n",$lines); } } }
if ($_SERVER['REQUEST_METHOD']==='POST') { admin_csrf_check(); $postAction=(string)($_POST['form_action']??'save'); $id=(int)($_POST['id']??0); if($postAction==='delete'){if($id>0){$s=$pdo->prepare('DELETE FROM products WHERE id=?');$s->execute([$id]);$_SESSION['flash']='Product deleted.';}redirect('products.php');}
$product=array_merge($product,$_POST); $name=trim((string)($_POST['name']??''));$sku=trim((string)($_POST['sku']??''));$slug=trim((string)($_POST['slug']??''));$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);$stock=filter_var($_POST['stock_quantity']??null,FILTER_VALIDATE_INT);$threshold=filter_var($_POST['low_stock_threshold']??null,FILTER_VALIDATE_INT);$cat=($_POST['category_id']??'')!==''?(int)$_POST['category_id']:null;$parentProduct=($_POST['parent_product_id']??'')!==''?(int)$_POST['parent_product_id']:null;if($parentProduct===$id&&$id>0)$errors[]='A product cannot be its own parent product.';$brand=($_POST['brand_id']??'')!==''?(int)$_POST['brand_id']:null; $newBrand=trim((string)($_POST['new_brand']??'')); if($newBrand!==''){ $brandSlug=slugify($newBrand); $bs=$pdo->prepare('INSERT INTO brands(name,slug,is_active) VALUES(?,?,1) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)'); $bs->execute([$newBrand,$brandSlug]); $brand=(int)$pdo->lastInsertId(); }
if($name===''||mb_strlen($name)>200)$errors[]='Product name is required (maximum 200 characters).';if($sku===''||mb_strlen($sku)>80)$errors[]='SKU is required (maximum 80 characters).';if($price===false||$price<0)$errors[]='Enter a valid non-negative price.';if($stock===false||$stock<0)$errors[]='Stock quantity must be zero or greater.';if($threshold===false||$threshold<0)$errors[]='Low-stock threshold must be zero or greater.';
$compare=trim((string)($_POST['compare_at_price']??''));$cost=trim((string)($_POST['cost_price']??''));foreach(['Compare-at price'=>$compare,'Cost price'=>$cost] as $label=>$v){if($v!==''&&(!is_numeric($v)||(float)$v<0))$errors[]="$label must be blank or a non-negative number.";}
$slug=slugify($slug!==''?$slug:$name);$specText=trim((string)($_POST['specifications']??''));$specData=[];foreach(preg_split('/\r\n|\r|\n/',$specText) as $line){$line=trim($line);if($line==='')continue;if(str_contains($line,':')){[$k,$v]=array_map('trim',explode(':',$line,2));if($k!=='')$specData[$k]=$v;}else{$specData[]=$line;}}$spec=$specData?json_encode($specData,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):'';
