if(!$errors){try{$values=[$cat,$parentProduct,$brand,$name,$slug,$sku,trim((string)($_POST['short_description']??''))?:null,trim((string)($_POST['description']??''))?:null,$spec!==''?$spec:null,(float)$price,$compare!==''?(float)$compare:null,$cost!==''?(float)$cost:null,(int)$stock,(int)$threshold,$imagePath?:null,isset($_POST['is_featured'])?1:0,isset($_POST['is_active'])?1:0];if($id>0){$values[]=$id;$sql='UPDATE products SET category_id=?,parent_product_id=?,brand_id=?,name=?,slug=?,sku=?,short_description=?,description=?,specifications=?,price=?,compare_at_price=?,cost_price=?,stock_quantity=?,low_stock_threshold=?,image_path=?,is_featured=?,is_active=? WHERE id=?';}else{$sql='INSERT INTO products (category_id,parent_product_id,brand_id,name,slug,sku,short_description,description,specifications,price,compare_at_price,cost_price,stock_quantity,low_stock_threshold,image_path,is_featured,is_active) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)';}$st=$pdo->prepare($sql);$st->execute($values);$_SESSION['flash']=$id>0?'Product updated successfully.':'Product added successfully.';redirect('products.php');}catch(PDOException $ex){$errors[]=$ex->getCode()==='23000'?'That SKU or slug is already in use.':'Could not save the product. Check the server error log.';}}
}
$isForm=in_array($action,['new','edit'],true)||($_SERVER['REQUEST_METHOD']==='POST'&&$action!=='');
if($isForm){admin_page_start($id>0?'Edit product':'Add product');if($errors):?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $err):?><li><?=e($err)?></li><?php endforeach;?></ul></div><?php endif;?><div class="panel"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?= (int)$id ?>"><input type="hidden" name="existing_image_path" value="<?=e((string)($product['image_path']??''))?>"><div class="row g-3"><div class="col-md-8"><label class="form-label">Product name *</label><input class="form-control" name="name" required maxlength="200" value="<?=e((string)($product['name']??''))?>"></div><div class="col-md-4"><label class="form-label">SKU *</label><input class="form-control" name="sku" required maxlength="80" value="<?=e((string)($product['sku']??''))?>"></div><div class="col-md-6"><label class="form-label">Slug (optional; generated from name if blank)</label><input class="form-control" name="slug" value="<?=e((string)($product['slug']??''))?>"></div><div class="col-md-3"><label class="form-label">Category</label><select class="form-select" name="category_id"><option value="">Uncategorised</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=((string)($product['category_id']??'')===(string)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Parent product / grouping</label><select class="form-select" name="parent_product_id"><option value="">None</option><?php foreach($parentProducts as $pp):if((int)$pp['id']===$id)continue;?><option value="<?=(int)$pp['id']?>" <?=((string)($product['parent_product_id']??'')===(string)$pp['id'])?'selected':''?>><?=e($pp['name'])?></option><?php endforeach;?></select><small class="text-secondary">Optional product family or parent listing.</small></div><div class="col-md-3"><label class="form-label">