ia-picker-item"><input type="radio" name="image_path" value="<?=e($mf)?>" <?=((string)($product['image_path']??'')===$mf)?'checked':''?>><img src="../<?=e($mf)?>" alt=""><span><?=e(substr(basename($mf),0,16))?></span></label><?php endforeach;?></div><small class="text-secondary">Select an image thumbnail, or upload a new image above. Manage files in Admin → Media.</small></div><div class="col-12"><label class="form-label">Short description</label><textarea class="form-control" name="short_description" rows="2" maxlength="500"><?=e((string)($product['short_description']??''))?></textarea></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="4"><?=e((string)($product['description']??''))?></textarea></div><div class="col-12"><label class="form-label">Specifications (one per line)</label><textarea class="form-control" name="specifications" rows="5" placeholder="Brand: Samsung&#10;Storage: 128GB&#10;RAM: 8GB&#10;Display: 6.5 inches"><?=e((string)($product['specifications']??''))?></textarea><small class="text-secondary">Type or paste one specification per line. Use “Label: Value” when you want a named field.</small></div><div class="col-12 d-flex flex-wrap gap-4"><div class="form-check"><input class="form-check-input" type="checkbox" name="is_featured" id="featured" <?=!empty($product['is_featured'])?'checked':''?>><label class="form-check-label" for="featured">Featured product</label></div><div class="form-check"><input class="form-check-input" type="checkbox" name="is_active" id="active" <?=!isset($product['is_active'])||!empty($product['is_active'])?'checked':''?>><label class="form-check-label" for="active">Active / visible in shop</label></div></div><div class="col-12 d-flex gap-2"><button class="btn btn-primary" type="submit">Save product</button><a class="btn btn-outline-secondary" href="products.php">Cancel</a></div></div></form></div><?php admin_page_end();exit;}
$q=trim((string)($_GET['q']??''));$sql='SELECT p.*,c.name AS category_name,b.name AS brand_name FROM products p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN brands b ON b.id=p.brand_id';$params=[];if($q!==''){$sql.=' WHERE p.name LIKE ? OR p.sku LIKE ? OR p.slug LIKE ?';$like='%'.$q.'%';$params=[$like,$like,$like];}$sql.=' ORDER BY p.created_at DESC LIMIT 250';$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();admin_page_start('Products');?><div class="panel"><div class="d-flex flex-wrap justify-content-between gap-2 mb-3"><form class="d-flex gap-2" method="get"><input class="form-control" name="q" placeholder="Search name or SKU" value="<?=e($q)?>"><button class="btn btn-outline-secondary">Search</button></form><a class="btn btn-primary" href="products.php?action=new"><i class="bi bi-plus-lg me-1"></i>Add product</a></div><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Product</th><th>SKU</th><th>Category / brand</th><th>Price</th><th>Stock</th><th>Visibility</th><th>Actions</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="text-center text-secondary py-4">No products found.</td></tr><?php else:foreach($rows as $r):?><tr><td><div class="d-flex align-items-center gap-2"><?php if($r['image_path']):?><img class="image-thumb" src="../<?=e((string)$r['image_path'])?>" alt=""><?php else:?><div class="image-thumb d-grid place-items-center text-secondary"><i class="bi bi-image"></i></div><?php endif;?><div><div class="fw-semibold"><?=e($r['name'])?></div><?php if($r['is_featured']):?><span class="badge text-bg-warning">Featured</span><?php endif;?></div></div></td><td><?=e($r['sku'])?></td><td><?=e($r['category_name']??'—')?> <div class="text-secondary small"><?=e($r['brand_name']??'No brand')?></div></td><td><?=e(money($r['price']))?></td><td><span class="badge <?=((int)$r['stock_quantity']<=(int)$r['low_stock_threshold'])?'text-bg-warning':'text-bg-light border'?>"><?= (int)$r['stock_quantity'] ?></span></td><td><?=!empty($r['is_active'])?'<span class="badge text-bg-success">Active</span>':'<span class="badge text-bg-secondary">Hidden</span>'?></td><td><div class="d-flex gap-1"><a class="btn btn-sm btn-outline-primary" href="products.php?action=edit&id=<?=(int)$r['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this product? This cannot be undone.');"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="form_action" value="delete"><button class="btn btn-sm btn-outline-danger">Delete</button></form></div></td></tr><?php endforeach;endif;?></tbody></table></div><div class="text-secondary small">Showing up to 250 products. Deleting a product does not delete historical order line details.</div></div><?php admin_page_end();
